    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<AcadCalender>(entity =>
        {
            entity.ToTable("AcadCalender");

            entity.Property(e => e.Id)
                .ValueGeneratedNever()
                .HasColumnName("id");
            entity.Property(e => e.Apr).HasMaxLength(2000);
            entity.Property(e => e.AprAct)
                .HasMaxLength(2000)
                .HasColumnName("Apr_Act");
            entity.Property(e => e.Aug).HasMaxLength(2000);
            entity.Property(e => e.AugAct)
                .HasMaxLength(2000)
                .HasColumnName("Aug_Act");
            entity.Property(e => e.Dec).HasMaxLength(2000);
            entity.Property(e => e.DecAct)
